export function discountPercent(isMember: boolean, hasCoupon: boolean): number {
  if (isMember && hasCoupon) return 15;
  if (isMember) return 10;
  if (hasCoupon) return 5;
  return 0;
}

cases.after:
export function discountPercent(isMember: boolean, hasCoupon: boolean): number {
  if (hasCoupon && isMember) return 15;
  if (isMember) return 10;
  if (hasCoupon) return 5;
  return 0;
}

cases.reference:
export function discountPercent(isMember: boolean, hasCoupon: boolean): number {
  return (isMember ? 10 : 0) + (hasCoupon ? 5 : 0);
}

