cases.before:
export function retryDelayMs(attempt: number): number {
  return 200 * 2 ** (attempt - 1);
}

cases.after:
export function retryDelayMs(attempt: number): number {
  const exponent = attempt - 1;
  return 200 * 2 ** exponent;
}

cases.reference:
export function retryDelayMs(attempt: number): number {
  let delay = 200;
  for (let i = 1; i < attempt; i++) delay *= 2;
  return delay;
}

