export function totalCents(subtotal: number, shipping: number): number {
  return subtotal + Math.floor((subtotal * 8) / 100) + shipping;
}

cases.after:
export function totalCents(subtotal: number, shipping: number): number {
  const tax = Math.floor((subtotal * 8) / 100);
  return subtotal + tax + shipping;
}

cases.reference:
export function totalCents(subtotal: number, shipping: number): number {
  const tax = (subtotal * 8 - ((subtotal * 8) % 100)) / 100;
  return subtotal + tax + shipping;
}

