export function formatPrice(cents: number): string {
  const dollars = (cents / 100).toFixed(2);
  return '$' + dollars;
}

cases.reference:
export function formatPrice(cents: number): string {
  const dollars = Math.floor(cents / 100);
  const rest = cents % 100;
  return '$' + dollars + '.' + (rest < 10 ? '0' + rest : String(rest));
}

